import { randomUUID } from "node:crypto";

import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

interface ApiError {
  error: { code: string; message?: string; [key: string]: unknown };
}

interface ExtractionRef {
  id: string;
}

const PDF_BYTES = Buffer.from("%PDF-1.4\n% lifecycle test document\n%%EOF\n");
const REQUIRED_KINDS = ["w9", "insurance_certificate", "contract"] as const;

async function waitForExtraction(api: APIRequestContext, documentId: string): Promise<ExtractionRef> {
  for (let attempt = 0; attempt < 60; attempt++) {
    const response = await api.get(`/api/documents/${documentId}/extraction`);
    if (response.status() === 200) {
      return await expectStatus<ExtractionRef>(response, 200);
    }
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
  throw new Error(`extraction for document ${documentId} never became available`);
}

test("resubmitting without replacing a rejected document is refused", { tag: "@LIF-04" }, async ({ apiAs }) => {
  // Arrange: a member creates a uniquely named vendor and uploads every required document.
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");

  const vendor = await expectStatus<{ id: string }>(
    await member.post("/api/vendors", {
      data: {
        name: `Lifecycle Vendor ${randomUUID()}`,
        category: "services",
        contact_email: `vendor-${randomUUID()}@example.test`,
      },
    }),
    201,
  );

  const documentsByKind: Record<string, { id: string }> = {};
  for (const kind of REQUIRED_KINDS) {
    documentsByKind[kind] = await expectStatus<{ id: string }>(
      await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind,
          file: { name: `${kind}-${randomUUID()}.pdf`, mimeType: "application/pdf", buffer: PDF_BYTES },
        },
      }),
      201,
    );
  }

  // Wait for extraction on the w9, then complete the first submission.
  const w9Extraction = await waitForExtraction(member, documentsByKind.w9.id);
  for (const kind of ["insurance_certificate", "contract"] as const) {
    await waitForExtraction(member, documentsByKind[kind].id);
  }
  await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

  // A reviewer rejects the w9 extraction.
  await expectStatus(
    await reviewer.post(`/api/extractions/${w9Extraction.id}/decision`, {
      data: { decision: "reject", note: "W-9 is illegible" },
    }),
    200,
  );

  // Act: the member resubmits without replacing the rejected w9.
  const response = await member.post(`/api/vendors/${vendor.id}/submit`);

  // Assert: refused, and only the w9 is reported as missing.
  const body = await expectStatus<ApiError>(response, 409);
  expect(body.error.code).toBe("documents_incomplete");

  const serializedError = JSON.stringify(body.error);
  expect(serializedError).toContain('"w9"');
  expect(serializedError).not.toContain('"insurance_certificate"');
  expect(serializedError).not.toContain('"contract"');
});
